INSERT INTO legal.provision_versions (version_key, provision_key, edition_date, edition_kind, changes_noted_on, edition_effective_from, snapshot_on, text, source_url, sha256, applicability_note) VALUES
    ('44fz/34/4@2026-11-25:cb293a87db32', '44fz/34/4', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '4. В контракт включается обязательное условие об ответственности заказчика и поставщика (подрядчика, исполнителя) за неисполнение или ненадлежащее исполнение обязательств, предусмотренных контрактом.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/c5cbc4acc59ffed792a3921dbc18900d2d0f7eb1/#dst100404', 'cb293a87db32bfcbfe548b70719c5d96aefc31b87ded48a5498a9283c7b656b5', NULL),
    ('44fz/34/5@2026-11-25:fc694f4b47f4', '44fz/34/5', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '5. В случае просрочки исполнения заказчиком обязательств, предусмотренных контрактом, а также в иных случаях неисполнения или ненадлежащего исполнения заказчиком обязательств, предусмотренных контрактом, поставщик (подрядчик, исполнитель) вправе потребовать уплаты неустоек (штрафов, пеней). Пеня начисляется за каждый день просрочки исполнения обязательства, предусмотренного контрактом, начиная со дня, следующего после дня истечения установленного контрактом срока исполнения обязательства. Такая пеня устанавливается контрактом в размере одной трехсотой действующей на дату уплаты пеней ключевой ставки Центрального банка Российской Федерации от не уплаченной в срок суммы. Штрафы начисляются за ненадлежащее исполнение заказчиком обязательств, предусмотренных контрактом, за исключением просрочки исполнения обязательств, предусмотренных контрактом. Размер штрафа устанавливается контрактом в порядке, установленном Правительством Российской Федерации.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/c5cbc4acc59ffed792a3921dbc18900d2d0f7eb1/#dst100405', 'fc694f4b47f4b963d6e8e59a32bc0870f149ef0d58674cbec41ac52331dae730', NULL),
    ('44fz/34/6@2026-11-25:329b762ca4e1', '44fz/34/6', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '6. В случае просрочки исполнения поставщиком (подрядчиком, исполнителем) обязательств (в том числе гарантийного обязательства), предусмотренных контрактом, а также в иных случаях неисполнения или ненадлежащего исполнения поставщиком (подрядчиком, исполнителем) обязательств, предусмотренных контрактом, заказчик направляет поставщику (подрядчику, исполнителю) требование об уплате неустоек (штрафов, пеней).', 'https://www.consultant.ru/document/cons_doc_LAW_144624/c5cbc4acc59ffed792a3921dbc18900d2d0f7eb1/#dst100406', '329b762ca4e1da8e6f09299cbb85bf13779444172a1b2395c15abc3f0f4f06db', NULL),
    ('44fz/34/7@2026-11-25:f4b42b285949', '44fz/34/7', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '7. Пеня начисляется за каждый день просрочки исполнения поставщиком (подрядчиком, исполнителем) обязательства, предусмотренного контрактом, начиная со дня, следующего после дня истечения установленного контрактом срока исполнения обязательства, и устанавливается контрактом в размере одной трехсотой действующей на дату уплаты пени ключевой ставки Центрального банка Российской Федерации от цены контракта (отдельного этапа исполнения контракта), уменьшенной на сумму, пропорциональную объему обязательств, предусмотренных контрактом (соответствующим отдельным этапом исполнения контракта) и фактически исполненных поставщиком (подрядчиком, исполнителем), за исключением случаев, если законодательством Российской Федерации установлен иной порядок начисления пени.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/c5cbc4acc59ffed792a3921dbc18900d2d0f7eb1/#dst100407', 'f4b42b2859496f43c76bb301cc883a14d81cd7376b8e8f76ba71e89eda3c5da2', NULL),
    ('44fz/34/8@2026-11-25:77015d2c72a8', '44fz/34/8', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '8. Штрафы начисляются за неисполнение или ненадлежащее исполнение поставщиком (подрядчиком, исполнителем) обязательств, предусмотренных контрактом, за исключением просрочки исполнения поставщиком (подрядчиком, исполнителем) обязательств (в том числе гарантийного обязательства), предусмотренных контрактом. Размер штрафа устанавливается контрактом в порядке, установленном Правительством Российской Федерации, за исключением случаев, если законодательством Российской Федерации установлен иной порядок начисления штрафов.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/c5cbc4acc59ffed792a3921dbc18900d2d0f7eb1/#dst100408', '77015d2c72a838e4f0c3a4e49f10f2c460910204077942cc6d529660074ac49d', NULL),
    ('44fz/34/9@2026-11-25:c8d7eee8db14', '44fz/34/9', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '9. Сторона освобождается от уплаты неустойки (штрафа, пени), если докажет, что неисполнение или ненадлежащее исполнение обязательства, предусмотренного контрактом, произошло вследствие непреодолимой силы или по вине другой стороны.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/c5cbc4acc59ffed792a3921dbc18900d2d0f7eb1/#dst100409', 'c8d7eee8db14fb581b2c0d459413d772610ab93105ab047a77624eebb67f2753', NULL),
    ('44fz/34/15@2026-11-25:9de2c5cab530', '44fz/34/15', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '15. При заключении контракта в случаях, предусмотренных пунктом 1, пунктами 4 и 5 (за исключением контрактов, заключенных в соответствии с частью 12 статьи 93 настоящего Федерального закона), пунктами 8, 9, 15, 20, 21, 22, 23, 26, 28, 29, 33, 37, 40, 41, 44, 45, 46, 50 - 53, 56, 63 части 1 статьи 93 настоящего Федерального закона, требования частей 4 - 9, 11 - 13 настоящей статьи заказчиком могут не применяться к указанному контракту. В этих случаях контракт может быть заключен в простой письменной форме в соответствии с положениями Гражданского кодекса Российской Федерации для совершения сделок.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/c5cbc4acc59ffed792a3921dbc18900d2d0f7eb1/#dst100415', '9de2c5cab5303bb6bfb066d0318b56f4083a20ca0607a8bab999f332a968f64c', NULL),
    ('44fz/34/14/1@2026-11-25:1724121024ae', '44fz/34/14/1', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1) о возможности одностороннего отказа от исполнения контракта в соответствии с положениями частей 8 - 11, 13 - 19, 21 - 23 и 25 статьи 95 настоящего Федерального закона;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/c5cbc4acc59ffed792a3921dbc18900d2d0f7eb1/#dst2244', '1724121024ae15ef4027951b405adddb5957fc081ced829b5ce2960273e88897', NULL),
    ('44fz/34/14/2@2026-11-25:36b51425e7a4', '44fz/34/14/2', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '2) об удержании суммы неисполненных поставщиком (подрядчиком, исполнителем) требований об уплате неустоек (штрафов, пеней), предъявленных заказчиком в соответствии с настоящим Федеральным законом, из суммы, подлежащей оплате поставщику (подрядчику, исполнителю).', 'https://www.consultant.ru/document/cons_doc_LAW_144624/c5cbc4acc59ffed792a3921dbc18900d2d0f7eb1/#dst2245', '36b51425e7a436d37bf10eb2c68b89d7e956918a373f6a91938daea51544ea00', NULL),
    ('44fz/95/1@2026-11-25:a395ba2d540a', '44fz/95/1', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1. Изменение существенных условий контракта при его исполнении не допускается, за исключением их изменения по соглашению сторон в следующих случаях:', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101310', 'a395ba2d540a431c79dbe8cc11e20de5d51dba69555c19680250e4f8d0e43187', NULL),
    ('44fz/95/1/1.1@2026-11-25:a1ec58087454', '44fz/95/1/1.1', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1.1) при снижении цены контракта без изменения предусмотренных контрактом количества товара, объема работы или услуги, качества поставляемого товара, выполняемой работы, оказываемой услуги и иных условий контракта;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst2977', 'a1ec58087454ddf69d98080bdda613396d048d3819983fa33cbe3cdb04f5fdf6', NULL),
    ('44fz/95/1/1.2@2026-11-25:3838521f8fc0', '44fz/95/1/1.2', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1.2) если по предложению заказчика увеличиваются предусмотренные контрактом (за исключением контракта, предметом которого является выполнение работ по строительству, реконструкции, капитальному ремонту, сносу объекта капитального строительства, благоустройству территории, геологическому изучению недр, проведению работ по сохранению объектов культурного наследия (памятников истории и культуры) народов Российской Федерации) количество товара, объем работы, объем услуги не более чем на десять процентов или уменьшаются предусмотренные контрактом количество поставляемого товара, объем выполняемой работы, объем оказываемой услуги не более чем на десять процентов. При этом по соглашению сторон допускается однократное увеличение с учетом положений бюджетного законодательства Российской Федерации цены контракта пропорционально дополнительному количеству товара, дополнительному объему работы, дополнительному объему услуги исходя из цены единицы товара, работы, услуги, но не более чем на десять процентов цены контракта. При уменьшении предусмотренных контрактом количества товара, объема работы, объема услуги стороны контракта обязаны уменьшить цену контракта исходя из цены единицы товара, работы, услуги. Цена единицы товара, работы, услуги в целях настоящего пункта определяется как частное от деления цены контракта на предусмотренные контрактом количество товара, объем работы, объем услуги. Если контрактом, заключенным по результатам применения конкурентного способа, или контрактом, заключенным в соответствии с пунктом 24 или 25 части 1 статьи 93 настоящего Федерального закона, предусмотрены поставка нескольких товаров, выполнение нескольких работ, оказание нескольких услуг, цена единицы товара, работы, услуги в целях настоящего пункта определяется путем уменьшения цены соответствующей единицы, использовавшейся заказчиком при определении в соответствии с настоящим Федеральным законом начальной (максимальной) цены контракта, пропорционально снижению начальной (максимальной) цены контракта, предложенному поставщиком (подрядчиком, исполнителем) при определении поставщика (подрядчика, исполнителя). Если контрактом, заключенным с единственным поставщиком (подрядчиком, исполнителем), за исключением контрактов, заключенных в соответствии с пунктом 24 или 25 части 1 статьи 93 настоящего Федерального закона, предусмотрены поставка нескольких товаров, выполнение нескольких работ, оказание нескольких услуг, в целях настоящего пункта используется цена единицы товара, работы, услуги, использовавшаяся заказчиком при определении в соответствии с настоящим Федеральным законом цены контракта, заключаемого с единственным поставщиком (подрядчиком, исполнителем). Если предметом контракта является поставка лекарственных препаратов, медицинских изделий, расходных материалов к ним, увеличение или уменьшение в соответствии с настоящим пунктом количества поставляемого товара, цены контракта допускается не более чем на тридцать процентов;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst2978', '3838521f8fc0ab8f89944313955e64c245cd003f3154037c355eaf78a1715719', 'Для увеличения или уменьшения до 30% количества и цены лекарственных препаратов, медицинских изделий и расходных материалов к ним проверить ч. 4 ст. 2 закона № 279-ФЗ. Этот фрагмент применяется с 01.01.2027.'),
    ('44fz/95/1/1.3@2026-11-25:0c466e4f888e', '44fz/95/1/1.3', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1.3) при изменении объема и (или) видов выполняемых работ по контракту, предметом которого является выполнение работ по строительству, реконструкции, капитальному ремонту, сносу объекта капитального строительства, благоустройству территории, геологическому изучению недр, проведению работ по сохранению объектов культурного наследия (памятников истории и культуры) народов Российской Федерации, а также по контрактам, предусмотренным частями 16 и 16.1 статьи 34 настоящего Федерального закона. При этом допускается изменение с учетом положений бюджетного законодательства Российской Федерации цены контракта не более чем на десять процентов цены контракта;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst2979', '0c466e4f888e850f07c6f2b521a3025537384739491290f1812c08b78a08ea6a', NULL),
    ('44fz/95/1/1.4@2026-11-25:0bd9b2d23fa9', '44fz/95/1/1.4', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1.4) если Правительством Российской Федерации принято решение о введении специальных мер в сфере экономики, предусмотренное пунктом 1 статьи 26.1 Федерального закона от 31 мая 1996 года N 61-ФЗ "Об обороне", и предметом контракта является поставка товара, выполнение работы, оказание услуги по государственному оборонному заказу. По предложению заказчиков, являющихся федеральными органами исполнительной власти, осуществляющими функции по выработке и реализации государственной политики в области обороны, в области гражданской обороны, защиты населения и территорий от чрезвычайных ситуаций природного и техногенного характера, в области государственной охраны, государственного управления в области обеспечения безопасности Российской Федерации, в сфере деятельности войск национальной гвардии Российской Федерации, допускается увеличение предусмотренных таким контрактом количества поставляемого товара, объема выполняемой работы или оказываемой услуги либо уменьшение предусмотренных таким контрактом количества поставляемого товара, объема выполняемой работы или оказываемой услуги. При этом допускается изменение цены контракта с учетом положений бюджетного законодательства Российской Федерации и в пределах основных показателей государственного оборонного заказа пропорционально дополнительному количеству товара, дополнительному объему работы или услуги исходя из установленной в контракте цены единицы товара, работы или услуги. При уменьшении предусмотренных контрактом количества поставляемого товара, объема выполняемой работы или оказываемой услуги стороны контракта обязаны уменьшить цену контракта исходя из цены единицы товара, работы или услуги. Цена единицы дополнительно поставляемого товара или цена единицы товара при уменьшении предусмотренного контрактом количества поставляемого товара должна определяться как частное от деления первоначальной цены контракта на предусмотренное в контракте количество такого товара;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst12171', '0bd9b2d23fa9d3da0d28089d376705924982ef02b6a22cc419484db78ffe60fa', NULL),
    ('44fz/95/1/1.5@2026-11-25:5c296c093956', '44fz/95/1/1.5', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1.5) если по предложению заказчика без изменения предусмотренной контрактом цены единицы товара, работы, услуги увеличивается максимальное значение цены контракта (в случае, предусмотренном частью 24 статьи 22 настоящего Федерального закона) не более чем на десять процентов без изменения иных существенных условий контракта;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst12515', '5c296c0939565de4a95060b4aa37aa49d93dfca566b75843879638cfeccd5dbd', NULL),
    ('44fz/95/1/1.6@2026-11-25:d6ddad175ad4', '44fz/95/1/1.6', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1.6) при замене предусмотренных контрактом товара, работы, услуги на товар, работу, услугу, функциональные, технические и качественные характеристики, эксплуатационные характеристики которых аналогичны или улучшены по сравнению с характеристиками, предусмотренными описанием объекта закупки или условиями заключенного с единственным поставщиком (подрядчиком, исполнителем) (за исключением случаев, установленных пунктами 24 и 25 части 1 статьи 93 настоящего Федерального закона) контракта;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst12516', 'd6ddad175ad40c47bcc737c12a14d95c7c419cd476110f5dd85ccb7bcd231cb4', NULL),
    ('44fz/95/1/1.7@2026-11-25:256482c4b533', '44fz/95/1/1.7', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1.7) при изменении предусмотренной контрактом страны происхождения товара при условии соблюдения положений подпункта "в" пункта 1, подпункта "б" пункта 2, подпункта "в" пункта 3 части 4 статьи 14 настоящего Федерального закона;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst12517', '256482c4b53332503b52d0738d160600a9d7077c02da6d68ff1bc1ec3fb9048e', NULL),
    ('44fz/95/1/1.8@2026-11-25:e8f726b1f22b', '44fz/95/1/1.8', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1.8) при изменении реквизитов счета поставщика (подрядчика, исполнителя), на который осуществляется перечисление денежных средств в качестве оплаты поставленного товара, выполненной работы (ее результатов), оказанной услуги, без изменения иных существенных условий контракта;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst12518', 'e8f726b1f22bb708cbe0c66cec8458103d5a15469d01160fa6c43dda8c9f2c0f', NULL),
    ('44fz/95/1/2@2026-11-25:6cbb92024bfb', '44fz/95/1/2', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '2) если цена заключенного для обеспечения федеральных нужд на срок не менее чем три года контракта составляет либо превышает размер цены, установленный Правительством Российской Федерации, и исполнение указанного контракта по независящим от сторон контракта обстоятельствам без изменения его условий невозможно, данные условия могут быть изменены на основании решения Правительства Российской Федерации;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101314', '6cbb92024bfb6593bfbae43001f258968ec0f8ba8dc3696ccf3356c85d1ba624', NULL),
    ('44fz/95/1/3@2026-11-25:91ec4ed27a1e', '44fz/95/1/3', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '3) если цена заключенного для обеспечения нужд субъекта Российской Федерации на срок не менее чем три года контракта составляет или превышает размер цены, установленный Правительством Российской Федерации, и исполнение указанного контракта по независящим от сторон контракта обстоятельствам без изменения его условий невозможно, данные условия могут быть изменены на основании решения высшего исполнительного органа субъекта Российской Федерации;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101315', '91ec4ed27a1e7ef4505b7f7eb52f1e559b749f3a77ffbf5751cda35e607e9be7', NULL),
    ('44fz/95/1/4@2026-11-25:cc5410f09a3d', '44fz/95/1/4', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '4) если цена заключенного для обеспечения муниципальных нужд на срок не менее одного года контракта составляет или превышает размер цены, установленный Правительством Российской Федерации, и исполнение указанного контракта по независящим от сторон контракта обстоятельствам без изменения его условий невозможно, указанные условия могут быть изменены на основании решения местной администрации;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101316', 'cc5410f09a3ddda0333d8cdac28463bf089a64796a8f11bc1d879b1fa9b681b3', NULL),
    ('44fz/95/1/5@2026-11-25:53000d5a32ac', '44fz/95/1/5', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '5) изменение в соответствии с законодательством Российской Федерации регулируемых цен (тарифов) на товары, работы, услуги;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101317', '53000d5a32ac380c1704935596af6bdf48057cd4a1ea5f42b3fa2b4bd67ad6cd', NULL),
    ('44fz/95/1/6@2026-11-25:548fff917b46', '44fz/95/1/6', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '6) в случаях, предусмотренных пунктом 6 статьи 161 Бюджетного кодекса Российской Федерации, при уменьшении ранее доведенных до государственного или муниципального заказчика как получателя бюджетных средств лимитов бюджетных обязательств. При этом государственный или муниципальный заказчик в ходе исполнения контракта обеспечивает согласование новых условий контракта, в том числе цены и (или) сроков исполнения контракта и (или) количества товара, объема работы или услуги, предусмотренных контрактом;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101318', '548fff917b46e293d93e4d68eafedcc56e9c1ca1d2a4b0ec7fe5f622b60bef33', NULL),
    ('44fz/95/1/7@2026-11-25:a8bef0dbecb3', '44fz/95/1/7', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '7) в случае заключения контракта с иностранной организацией на лечение гражданина Российской Федерации за пределами территории Российской Федерации цена контракта может быть изменена при увеличении или уменьшении по медицинским показаниям перечня услуг, связанных с лечением гражданина Российской Федерации;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101793', 'a8bef0dbecb320b20eed9d83c45890ceb8812a66e0f11f65de117f5752035441', NULL),
    ('44fz/95/1/8@2026-11-25:7f43b35d5092', '44fz/95/1/8', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '8) если при исполнении заключенного на срок не менее одного года контракта, предусмотренного частью 16 (при условии, что контракт жизненного цикла предусматривает проектирование, строительство, реконструкцию, капитальный ремонт объекта капитального строительства) и частью 16.1 статьи 34 настоящего Федерального закона, контракта, предметом которого является выполнение работ по строительству, реконструкции, капитальному ремонту, сносу объекта капитального строительства, геологическому изучению недр, проведению работ по сохранению объектов культурного наследия, цена которого составляет или превышает предельный размер (предельные размеры) цены, установленный Правительством Российской Федерации, возникли независящие от сторон контракта обстоятельства, влекущие невозможность его исполнения, в том числе необходимость внесения изменений в проектную документацию. Предусмотренное настоящим пунктом изменение осуществляется при наличии в письменной форме обоснования такого изменения на основании решения Правительства Российской Федерации, высшего исполнительного органа субъекта Российской Федерации, местной администрации при осуществлении закупки для федеральных нужд, нужд субъекта Российской Федерации, муниципальных нужд соответственно и при условии, что такое изменение не приведет к увеличению срока исполнения контракта и (или) цены контракта более чем на тридцать процентов. При этом в указанный срок не включается срок получения в соответствии с законодательством Российской Федерации положительного заключения экспертизы проектной документации в случае необходимости внесения в нее изменений;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst1320', '7f43b35d5092e5eaa3b06d988904b40a860078cd0a3f3e0bea1d056eb045e1b8', NULL),
    ('44fz/95/1/9@2026-11-25:1eb72862e1fa', '44fz/95/1/9', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '9) если контракт, предусмотренный частью 16 (при условии, что контракт жизненного цикла предусматривает проектирование, строительство, реконструкцию, капитальный ремонт объекта капитального строительства) и частью 16.1 статьи 34 настоящего Федерального закона, контракт, предметом которого является выполнение работ по строительству, реконструкции, капитальному ремонту, сносу объекта капитального строительства, геологическому изучению недр, проведению работ по сохранению объектов культурного наследия, по независящим от сторон контракта обстоятельствам, влекущим невозможность его исполнения, в том числе необходимость внесения изменений в проектную документацию, либо по вине подрядчика не исполнен в установленный в контракте срок, допускается однократное изменение срока исполнения контракта на срок, не превышающий срока исполнения контракта, предусмотренного при его заключении. При этом в случае, если обеспечение исполнения контракта осуществлено путем внесения денежных средств, по соглашению сторон определяется новый срок возврата заказчиком подрядчику денежных средств, внесенных в качестве обеспечения исполнения контракта. В случае неисполнения контракта в срок по вине подрядчика предусмотренное настоящим пунктом изменение срока осуществляется при условии отсутствия неисполненных подрядчиком требований об уплате неустоек (штрафов, пеней), предъявленных заказчиком в соответствии с настоящим Федеральным законом, предоставления подрядчиком в соответствии с настоящим Федеральным законом обеспечения исполнения контракта;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst1321', '1eb72862e1fa945c158b64e7be720f5ea786561bc582aa3913d82866020e6445', NULL),
    ('44fz/95/1/10@2026-11-25:13c76e5a56a7', '44fz/95/1/10', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '10) в случае заключения контракта с единственным поставщиком (подрядчиком, исполнителем) в соответствии с пунктами 1, 3, 6, 8, 21, 22, 23, 29, 32, 34, 40, 41, 46, 51, 52, 56, 59 и 62 части 1 статьи 93 настоящего Федерального закона;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst1322', '13c76e5a56a74987fda8905f10a31675cccfbd202f6cc6307896e3cd18065ab6', NULL),
    ('44fz/95/1/11@2026-11-25:70f8701a1950', '44fz/95/1/11', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '11) если при исполнении контракта, предусмотренного частью 16 (при условии, что контракт жизненного цикла предусматривает проектирование, строительство, реконструкцию, капитальный ремонт объекта капитального строительства) и частью 16.1 статьи 34 настоящего Федерального закона, сметная стоимость строительства, реконструкции, капитального ремонта, определенная по результатам проверки на предмет достоверности ее определения в ходе проведения государственной экспертизы проектной документации, превышает цену такого контракта. Предусмотренное настоящим пунктом изменение существенных условий осуществляется с учетом такой сметной стоимости строительства, реконструкции, капитального ремонта объекта капитального строительства на основании решения Правительства Российской Федерации, высшего исполнительного органа субъекта Российской Федерации, местной администрации при осуществлении закупки для федеральных нужд, нужд субъекта Российской Федерации, муниципальных нужд соответственно и при условии, что такое изменение существенных условий не приведет к увеличению цены контракта более чем на тридцать процентов;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst2983', '70f8701a195006977a61bde5c2cddd34c92876cfd97084a681d9b2044b649553', NULL),
    ('44fz/95/1/12@2026-11-25:999aab0db279', '44fz/95/1/12', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '12) если при исполнении контракта изменяется срок исполнения отдельного этапа (отдельных этапов) исполнения контракта в рамках срока исполнения контракта, предусмотренного при его заключении;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst2984', '999aab0db279d7499c7a373e8e63ee4c1468ad8b9de2793e3b2db5185236f187', NULL),
    ('44fz/95/1/13@2026-11-25:7bef767d970a', '44fz/95/1/13', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '13) если при исполнении заключенного на срок не менее одного года контракта, предметом которого является выполнение научно-исследовательских, опытно-конструкторских или технологических работ, цена которого составляет или превышает предельный размер (предельные размеры) цены, установленный Правительством Российской Федерации, возникли независящие от сторон контракта обстоятельства, влекущие невозможность его исполнения. Предусмотренное настоящим пунктом изменение осуществляется при наличии в письменной форме обоснования такого изменения на основании решения Правительства Российской Федерации, высшего исполнительного органа субъекта Российской Федерации, местной администрации при осуществлении закупки для федеральных нужд, нужд субъекта Российской Федерации, муниципальных нужд соответственно и при условии, что такое изменение не приведет к увеличению срока исполнения контракта и (или) цены контракта более чем на тридцать процентов;', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst2985', '7bef767d970a595245952ee7fd36c4aa2ac18ab25e45dd1bc00b707a5ddabab9', NULL),
    ('44fz/95/1/14@2026-11-25:69a4c84a0c03', '44fz/95/1/14', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '14) если возникла необходимость изменения срока исполнения контракта на выполнение работ по строительному контролю вследствие и в пределах увеличения (уменьшения) срока исполнения контракта на выполнение работ по строительству, реконструкции, капитальному ремонту объекта капитального строительства, в процессе которых осуществляется строительный контроль, без изменения иных существенных условий контракта на выполнение работ по строительному контролю.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst12491', '69a4c84a0c0304cb3afc7ebda7ab0d3132121ba8bd9d02e3eaec5e698f980aa9', NULL),
    ('44fz/95/1.2@2026-11-25:6f7b6dc04aa1', '44fz/95/1.2', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1.2. В случае, если при исполнении контракта, предусмотренного частью 16 (при условии, что контракт жизненного цикла предусматривает проектирование, строительство, реконструкцию, капитальный ремонт объекта капитального строительства) и частью 16.1 статьи 34 настоящего Федерального закона, цена такого контракта превышает сметную стоимость строительства, реконструкции, капитального ремонта объекта капитального строительства, определенную по результатам проверки на предмет достоверности ее определения в ходе проведения государственной экспертизы проектной документации, цена такого контракта должна быть уменьшена с учетом указанной сметной стоимости строительства, реконструкции, капитального ремонта объекта капитального строительства.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst2986', '6f7b6dc04aa1e8213010a6f6a66c70f9c40df9a1cc49a758083b2268880726b6', NULL),
    ('44fz/95/1.3@2026-11-25:f708677e0e76', '44fz/95/1.3', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1.3. Предусмотренные частью 1 настоящей статьи изменения осуществляются при условии предоставления поставщиком (подрядчиком, исполнителем) в соответствии с настоящим Федеральным законом обеспечения исполнения контракта, если такие изменения влекут возникновение новых обязательств поставщика (подрядчика, исполнителя), не обеспеченных ранее предоставленным обеспечением исполнения контракта, и если при определении поставщика (подрядчика, исполнителя) требование обеспечения исполнения контракта установлено в соответствии со статьей 96 настоящего Федерального закона. При этом:
