-- Федеральные нормы для анализатора закупок. Срез на 2026-11-25.
-- Запуск: psql -X -v ON_ERROR_STOP=1 -d ИМЯ_БАЗЫ -f import_legal_norms.sql
-- snapshot_on — дата подтверждённого среза текста.
-- edition_effective_from — дата вступления редакции акта по заголовку источника,
-- когда она указана. Особые сроки и переходные условия сохранены в тексте и примечаниях.
-- check_provisions перечисляет нормы-кандидаты. Применимость требует данных закупки.
BEGIN;
SET LOCAL standard_conforming_strings = on;
CREATE SCHEMA IF NOT EXISTS legal;

CREATE TABLE IF NOT EXISTS legal.acts (
    act_key text PRIMARY KEY,
    number text,
    title text NOT NULL,
    adopted_on date NOT NULL,
    kind text NOT NULL CHECK (kind IN ('law', 'code', 'decree', 'court_review', 'amendment', 'customer_regulation')),
    official_url text
);

CREATE TABLE IF NOT EXISTS legal.provisions (
    provision_key text PRIMARY KEY,
    act_key text NOT NULL REFERENCES legal.acts (act_key),
    locator_code text NOT NULL,
    locator text NOT NULL,
    UNIQUE (act_key, locator_code)
);

CREATE TABLE IF NOT EXISTS legal.provision_versions (
    version_key text PRIMARY KEY,
    provision_key text NOT NULL REFERENCES legal.provisions (provision_key),
    edition_date date NOT NULL,
    edition_kind text NOT NULL CHECK (edition_kind IN ('edition', 'original')),
    changes_noted_on date,
    edition_effective_from date,
    snapshot_on date NOT NULL,
    text text NOT NULL CHECK (length(btrim(text)) > 0),
    source_url text NOT NULL CHECK (source_url LIKE 'https://%'),
    sha256 text NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    applicability_note text,
    UNIQUE (provision_key, snapshot_on),
    CHECK (edition_date <= snapshot_on),
    CHECK (edition_effective_from IS NULL OR edition_effective_from <= snapshot_on)
);

CREATE TABLE IF NOT EXISTS legal.check_provisions (
    check_code text NOT NULL CHECK (check_code IN ('unilateral_refusal', 'auto_renewal', 'asymmetric_penalty')),
    procurement_law text NOT NULL CHECK (procurement_law IN ('44-ФЗ', '223-ФЗ')),
    contract_type text NOT NULL CHECK (contract_type IN ('all', 'supply', 'services', 'works')),
    provision_key text NOT NULL REFERENCES legal.provisions (provision_key),
    context text NOT NULL,
    PRIMARY KEY (check_code, procurement_law, contract_type, provision_key)
);

ON CONFLICT (act_key) DO NOTHING;

ON CONFLICT (provision_key) DO NOTHING;

1) размер обеспечения может быть уменьшен в порядке и случаях, предусмотренных частями 7 - 7.3 статьи 96 настоящего Федерального закона;
2) обеспечение исполнения контракта может быть предоставлено путем внесения соответствующих изменений в условия ранее предоставленной заказчику независимой гарантии;
3) если обеспечение исполнения контракта осуществляется путем предоставления новой независимой гарантии, возврат заказчиком ранее предоставленной ему независимой гарантии предоставившему ее гаранту не осуществляется, взыскание по ней не производится, заказчик признается отказавшимся от своих прав по ранее предоставленной независимой гарантии, обязательство гаранта перед заказчиком по ранее предоставленной независимой гарантии прекращается с момента выдачи новой независимой гарантии;
4) если при увеличении в соответствии с настоящей статьей цены контракта обеспечение исполнения контракта осуществляется путем внесения денежных средств, поставщик (подрядчик, исполнитель) вносит на счет, на котором в соответствии с законодательством Российской Федерации учитываются операции со средствами, поступающими заказчику, денежные средства в размере, пропорциональном стоимости новых обязательств поставщика (подрядчика, исполнителя).', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst2987', 'f708677e0e76fb6e691bbbed1dba2e4fc65f3d37eea46075f65b8016bdf49498', NULL),
    ('44fz/95/1.4@2026-11-25:443c11bfabcd', '44fz/95/1.4', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1.4. В случае уменьшения в соответствии с настоящей статьей цены контракта заказчик возвращает поставщику (подрядчику, исполнителю) внесенные в качестве обеспечения исполнения контракта денежные средства в размере, пропорциональном размеру такого уменьшения цены контракта.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst2992', '443c11bfabcd1589c67756df444c6d05cd109f06cc3ee88e1bd31f32c6f7b5cd', NULL),
    ('44fz/95/1.5@2026-11-25:8f75bb12c936', '44fz/95/1.5', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1.5. В случае изменения срока исполнения контракта в соответствии с частью 27 статьи 34 настоящего Федерального закона по соглашению сторон устанавливается новый срок возврата заказчиком поставщику (подрядчику, исполнителю) денежных средств, внесенных в качестве обеспечения исполнения контракта.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst2993', '8f75bb12c936c25fdd08f8f7e92a746c13852949000caf9c2571cce3f5a1232b', NULL),
    ('44fz/95/1.6@2026-11-25:64b4c48471a7', '44fz/95/1.6', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1.6. Государственным или муниципальным заказчиком как получателем бюджетных средств предусмотренные частью 1 настоящей статьи изменения могут быть осуществлены в пределах доведенных в соответствии с бюджетным законодательством Российской Федерации лимитов бюджетных обязательств на срок исполнения контракта.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst12293', '64b4c48471a737b5cf7db5dc933ddd984e3d14daf678b7ef48b04ac2b4f0c092', NULL),
    ('44fz/95/1.7@2026-11-25:249ea7f0a3d4', '44fz/95/1.7', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '1.7. Соглашение об изменении условий контракта, заключенного по результатам электронных процедур, закрытых электронных процедур, заключается с использованием единой информационной системы. В случаях, предусмотренных частью 5 статьи 103 настоящего Федерального закона, такое соглашение не размещается на официальном сайте.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst12427', '249ea7f0a3d46d09e03b2a5bb2a7b90e401cdfd5e8a2a8c72013f2e12698953c', NULL),
    ('44fz/95/8@2026-11-25:cc2c5a7a6ef3', '44fz/95/8', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '8. Расторжение контракта допускается по соглашению сторон, по решению суда, в случае одностороннего отказа стороны контракта от исполнения контракта в соответствии с гражданским законодательством.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst12294', 'cc2c5a7a6ef35021143be666f957a184f893ac2f91f4d45f3c3b555d48f3f4c1', NULL),
    ('44fz/95/9@2026-11-25:dfd6966f4621', '44fz/95/9', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '9. Заказчик вправе принять решение об одностороннем отказе от исполнения контракта по основаниям, предусмотренным Гражданским кодексом Российской Федерации для одностороннего отказа от исполнения отдельных видов обязательств, при условии, если это было предусмотрено контрактом.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101326', 'dfd6966f4621ae5d8119ab133c09314a31a6e3ff86358b6bdfaee3fdd3c7f2d0', NULL),
    ('44fz/95/10@2026-11-25:d842436d9160', '44fz/95/10', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '10. Заказчик вправе провести экспертизу поставленного товара, выполненной работы, оказанной услуги с привлечением экспертов, экспертных организаций до принятия решения об одностороннем отказе от исполнения контракта в соответствии с частью 8 настоящей статьи.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101327', 'd842436d9160f9d949a9f245d3a1915de958cce4905630a587d060012810c01f', NULL),
    ('44fz/95/11@2026-11-25:f0630343b686', '44fz/95/11', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '11. Если заказчиком проведена экспертиза поставленного товара, выполненной работы или оказанной услуги с привлечением экспертов, экспертных организаций, решение об одностороннем отказе от исполнения контракта может быть принято заказчиком только при условии, что по результатам экспертизы поставленного товара, выполненной работы или оказанной услуги в заключении эксперта, экспертной организации будут подтверждены нарушения условий контракта, послужившие основанием для одностороннего отказа заказчика от исполнения контракта.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101328', 'f0630343b6862f45aca65eb68e579bbba8f6d73a8a1be149271d1a6622053e02', NULL),
    ('44fz/95/12.1@2026-11-25:90176844fb2b', '44fz/95/12.1', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '12.1. В случае принятия заказчиком предусмотренного частью 9 настоящей статьи решения об одностороннем отказе от исполнения контракта, заключенного по результатам проведения электронных процедур, закрытых электронных процедур:
1) заказчик с использованием единой информационной системы формирует решение об одностороннем отказе от исполнения контракта, подписывает его усиленной электронной подписью лица, имеющего право действовать от имени заказчика, и размещает такое решение в единой информационной системе. В случаях, предусмотренных частью 5 статьи 103 настоящего Федерального закона, такое решение не размещается на официальном сайте;
2) решение об одностороннем отказе от исполнения контракта не позднее одного часа с момента его размещения в единой информационной системе в соответствии с пунктом 1 настоящей части автоматически с использованием единой информационной системы направляется поставщику (подрядчику, исполнителю). Датой поступления поставщику (подрядчику, исполнителю) решения об одностороннем отказе от исполнения контракта считается дата размещения в соответствии с настоящим пунктом такого решения в единой информационной системе в соответствии с часовой зоной, в которой расположен поставщик (подрядчик, исполнитель);
3) поступление решения об одностороннем отказе от исполнения контракта в соответствии с пунктом 2 настоящей части считается надлежащим уведомлением поставщика (подрядчика, исполнителя) об одностороннем отказе от исполнения контракта.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst2998', '90176844fb2bf3b8f0e0d4bf9be3f31f7060916b8d161b6b4e080029642f3d1a', NULL),
    ('44fz/95/12.2@2026-11-25:a99c3e36d049', '44fz/95/12.2', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '12.2. В случае принятия заказчиком предусмотренного частью 9 настоящей статьи решения об одностороннем отказе от исполнения контракта, заключенного по результатам проведения закрытого конкурса, закрытого аукциона, при осуществлении закупок, предусмотренных статьей 93 (за исключением закупки, осуществляемой в соответствии с частью 12 статьи 93 настоящего Федерального закона), статьей 111 (в случае определения в соответствии с частью 1 статьи 111 настоящего Федерального закона особенностей, предусматривающих неразмещение информации и документов в единой информационной системе, на официальном сайте при определении поставщика (подрядчика, исполнителя) и статьей 111.1 настоящего Федерального закона, такое решение передается лицу, имеющему право действовать от имени поставщика (подрядчика, исполнителя), лично под расписку или направляется поставщику (подрядчику, исполнителю) с соблюдением требований законодательства Российской Федерации о государственной тайне по адресу поставщика (подрядчика, исполнителя), указанному в контракте. Выполнение заказчиком требований настоящей части считается надлежащим уведомлением поставщика (подрядчика, исполнителя) об одностороннем отказе от исполнения контракта. Датой такого надлежащего уведомления считается:
1) дата, указанная лицом, имеющим право действовать от имени поставщика (подрядчика, исполнителя), в расписке о получении решения об одностороннем отказе от исполнения контракта (в случае передачи такого решения лицу, имеющему право действовать от имени поставщика (подрядчика, исполнителя), лично под расписку);
2) дата получения заказчиком подтверждения о вручении поставщику (подрядчику, исполнителю) заказного письма, предусмотренного настоящей частью, либо дата получения заказчиком информации об отсутствии поставщика (подрядчика, исполнителя) по адресу, указанному в контракте, информации о возврате такого письма по истечении срока хранения (в случае направления решения об одностороннем отказе от исполнения контракта заказным письмом).', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst3002', 'a99c3e36d049e6118e11a6a7cbe44190db10177eb1c83d709b5db9a6195a0038', NULL),
    ('44fz/95/13@2026-11-25:1b42a3913ede', '44fz/95/13', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '13. Решение заказчика об одностороннем отказе от исполнения контракта вступает в силу и контракт считается расторгнутым через десять дней с даты надлежащего уведомления заказчиком поставщика (подрядчика, исполнителя) об одностороннем отказе от исполнения контракта.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101330', '1b42a3913ede362467221296aaa97692b6cc01f26e4fcb9b783a17c849b44adb', NULL),
    ('44fz/95/14@2026-11-25:4a9e9b387a15', '44fz/95/14', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '14. Заказчик обязан отменить не вступившее в силу решение об одностороннем отказе от исполнения контракта, если в течение десятидневного срока с даты надлежащего уведомления поставщика (подрядчика, исполнителя) о принятом решении об одностороннем отказе от исполнения контракта устранено нарушение условий контракта, послужившее основанием для принятия указанного решения, а также заказчику компенсированы затраты на проведение экспертизы в соответствии с частью 10 настоящей статьи. Данное правило не применяется в случае повторного нарушения поставщиком (подрядчиком, исполнителем) условий контракта, которые в соответствии с гражданским законодательством являются основанием для одностороннего отказа заказчика от исполнения контракта.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101331', '4a9e9b387a15bed4a7c6a1a648c95f4a9fb36c7c45fc5586c8b2343cb02ed34c', NULL),
    ('44fz/95/14.1@2026-11-25:f0ce3732e1b3', '44fz/95/14.1', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '14.1. В случае отмены заказчиком в соответствии с настоящим Федеральным законом не вступившего в силу решения об одностороннем отказе от исполнения контракта, размещенного в единой информационной системе в соответствии с частью 12.1 настоящей статьи, заказчик не позднее одного дня, следующего за днем такой отмены, формирует с использованием единой информационной системы извещение об отмене решения об одностороннем отказе от исполнения контракта, подписывает его усиленной электронной подписью лица, имеющего право действовать от имени заказчика, и размещает такое извещение в единой информационной системе. В случаях, предусмотренных частью 5 статьи 103 настоящего Федерального закона, такое извещение не размещается на официальном сайте.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst3005', 'f0ce3732e1b3b67769a9488a528f57d26a63c20f21a364cfb39e1fd10a7104b3', NULL),
    ('44fz/95/14.2@2026-11-25:81606d6e9549', '44fz/95/14.2', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '14.2. В случае отмены заказчиком в соответствии с настоящим Федеральным законом не вступившего в силу решения об одностороннем отказе от исполнения контракта, заключенного по результатам проведения закрытого конкурса, закрытого аукциона, при осуществлении закупок, предусмотренных статьей 93 (за исключением закупки, осуществляемой в соответствии с частью 12 статьи 93 настоящего Федерального закона), статьей 111 (в случае определения в соответствии с частью 1 статьи 111 настоящего Федерального закона особенностей, предусматривающих неразмещение информации и документов в единой информационной системе, на официальном сайте при определении поставщика (подрядчика, исполнителя) и статьей 111.1 настоящего Федерального закона, заказчик не позднее трех рабочих дней, следующих за днем такой отмены, передает лицу, имеющему право действовать от имени поставщика (подрядчика, исполнителя), лично под расписку или направляет поставщику (подрядчику, исполнителю) с соблюдением требований законодательства Российской Федерации о государственной тайне по адресу поставщика (подрядчика, исполнителя), указанному в контракте, уведомление об отмене решения об одностороннем отказе от исполнения контракта.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst3006', '81606d6e9549876556ad25e54247e88d09dc024a4b8b5ac12c4073d0382c84ef', NULL),
    ('44fz/95/15@2026-11-25:54f687faaa51', '44fz/95/15', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '15. Заказчик обязан принять решение об одностороннем отказе от исполнения контракта в случаях:
1) если в ходе исполнения контракта установлено, что:
а) поставщик (подрядчик, исполнитель) и (или) поставляемый товар перестали соответствовать установленным извещением об осуществлении закупки и (или) документацией о закупке (если настоящим Федеральным законом предусмотрена документация о закупке) требованиям к участникам закупки (за исключением требования, предусмотренного частью 1.1 (при наличии такого требования) статьи 31 настоящего Федерального закона) и (или) поставляемому товару;
б) при определении поставщика (подрядчика, исполнителя) поставщик (подрядчик, исполнитель) представил недостоверную информацию о своем соответствии и (или) соответствии поставляемого товара требованиям, указанным в подпункте "а" настоящего пункта, что позволило ему стать победителем определения поставщика (подрядчика, исполнителя);
в) если вследствие реорганизации юридического лица, являющегося подрядчиком (исполнителем), его права и обязанности по такому контракту перешли к вновь возникшему юридическому лицу, зарегистрированному на территории иностранного государства, в отношении которого в соответствии с подпунктами "а" и "б" пункта 1 части 2 статьи 14 настоящего Федерального закона установлены запрет закупок работ, услуг, соответственно выполняемых, оказываемых иностранными лицами, либо ограничение закупок работ, услуг, соответственно выполняемых, оказываемых иностранными лицами, и подрядчик (исполнитель) являлся российским лицом, либо в соответствии с подпунктом "в" пункта 1 части 2 статьи 14 настоящего Федерального закона установлено преимущество в отношении работ, услуг, соответственно выполняемых, оказываемых российскими лицами, и подрядчик (исполнитель) являлся российским лицом;
2) если в ходе исполнения заключенного в соответствии с пунктом 47 части 1 статьи 93 настоящего Федерального закона контракта на поставку товара, производство которого создано или модернизировано и (или) освоено на территории Российской Федерации в соответствии со специальным инвестиционным контрактом, такой специальный инвестиционный контракт расторгнут. При этом расторжение контракта, заключенного в соответствии с пунктом 47 части 1 статьи 93 настоящего Федерального закона, осуществляется в следующем порядке:
а) сторона специального инвестиционного контракта, которая заключила такой контракт от имени Российской Федерации (Российской Федерации наряду с субъектом Российской Федерации и (или) муниципальным образованием), направляет в течение десяти рабочих дней со дня его расторжения уведомление об указанном расторжении заказчикам, заключившим в соответствии с пунктом 47 части 1 статьи 93 настоящего Федерального закона контракты на поставку товара, обязательства по которым не исполнены на дату направления такого уведомления. Уведомление о расторжении специального инвестиционного контракта направляется заказчикам по почте заказными письмами с уведомлением о вручении по адресам заказчиков, указанным в контрактах. Перечень соответствующих заказчиков определяется на основании информации, содержащейся в реестре контрактов, заключенных заказчиками;
б) заказчики не позднее трех рабочих дней с даты получения указанного в подпункте "а" настоящего пункта уведомления обязаны принять решение об одностороннем отказе от исполнения контракта, заключенного в соответствии с пунктом 47 части 1 статьи 93 настоящего Федерального закона;
в) расторжение контракта после принятия решения, указанного в подпункте "б" настоящего пункта, осуществляется в соответствии с общим порядком, предусмотренным настоящей статьей;
3) если в ходе исполнения контракта, заключенного в соответствии с пунктом 48 части 1 статьи 93 настоящего Федерального закона, расторгнут контракт со встречными инвестиционными обязательствами, заключенный в соответствии со статьей 111.4 настоящего Федерального закона. При этом расторжение контракта, заключенного в соответствии с пунктом 48 части 1 статьи 93 настоящего Федерального закона, осуществляется в следующем порядке:
а) сторона контракта со встречными инвестиционными обязательствами, которая заключила такой контракт от имени субъекта Российской Федерации согласно статье 111.4 настоящего Федерального закона, направляет в течение десяти рабочих дней со дня его расторжения уведомления об указанном расторжении заказчикам, заключившим в соответствии с пунктом 48 части 1 статьи 93 настоящего Федерального закона контракты, обязательства по которым не исполнены на дату направления таких уведомлений. Уведомление о расторжении контракта со встречными инвестиционными обязательствами, заключенного согласно статье 111.4 настоящего Федерального закона, направляется заказчикам по почте заказными письмами с уведомлением о вручении по адресам заказчиков, указанным в контрактах. Перечень соответствующих заказчиков определяется на основании информации, содержащейся в реестре контрактов, заключенных заказчиками;
б) заказчики в течение трех рабочих дней с даты получения указанного в подпункте "а" настоящего пункта уведомления обязаны принять решение об одностороннем отказе от исполнения контракта, заключенного в соответствии с пунктом 48 части 1 статьи 93 настоящего Федерального закона;
в) расторжение контракта после принятия решения, указанного в подпункте "б" настоящего пункта, осуществляется в соответствии с общим порядком, предусмотренным настоящей статьей.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101332', '54f687faaa51738478f10d16f40c5d9cc10e9c428cd962c61c984d7589fb82f2', NULL),
    ('44fz/95/19@2026-11-25:5898ee7bdfaa', '44fz/95/19', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '19. Поставщик (подрядчик, исполнитель) вправе принять решение об одностороннем отказе от исполнения контракта по основаниям, предусмотренным Гражданским кодексом Российской Федерации для одностороннего отказа от исполнения отдельных видов обязательств, если в контракте было предусмотрено право заказчика принять решение об одностороннем отказе от исполнения контракта.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101336', '5898ee7bdfaa12ffbe794fac299e8f152fec5dbd7c105ab42ee4660ea1167673', NULL),
    ('44fz/95/20.1@2026-11-25:20f415ce4f99', '44fz/95/20.1', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '20.1. В случае принятия поставщиком (подрядчиком, исполнителем) предусмотренного частью 19 настоящей статьи решения об одностороннем отказе от исполнения контракта, заключенного по результатам проведения электронных процедур, закрытых электронных процедур, такое решение направляется заказчику в следующем порядке:
1) поставщик (подрядчик, исполнитель) с использованием единой информационной системы формирует решение об одностороннем отказе от исполнения контракта, подписывает его усиленной электронной подписью лица, имеющего право действовать от имени поставщика (подрядчика, исполнителя), и размещает такое решение в единой информационной системе. В случаях, предусмотренных частью 5 статьи 103 настоящего Федерального закона, такое решение не размещается на официальном сайте;
2) решение об одностороннем отказе от исполнения контракта не позднее одного часа с момента его размещения в единой информационной системе в соответствии с пунктом 1 настоящей части автоматически с использованием единой информационной системы направляется заказчику. Датой поступления заказчику решения об одностороннем отказе от исполнения контракта считается дата размещения в соответствии с настоящим пунктом такого решения в единой информационной системе в соответствии с часовой зоной, в которой расположен заказчик;
3) поступление решения об одностороннем отказе от исполнения контракта в соответствии с пунктом 2 настоящей части считается надлежащим уведомлением заказчика об одностороннем отказе от исполнения контракта.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst3020', '20f415ce4f991cc7a778d5e322330bc17871b540f31fbf16d286cf740d6d917d', NULL),
    ('44fz/95/20.2@2026-11-25:1ffbeaaa8214', '44fz/95/20.2', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '20.2. В случае принятия поставщиком (подрядчиком, исполнителем) предусмотренного частью 19 настоящей статьи решения об одностороннем отказе от исполнения контракта, заключенного по результатам проведения закрытого конкурса, закрытого аукциона, при осуществлении закупок, предусмотренных статьей 93 (за исключением закупки, осуществляемой в соответствии с частью 12 статьи 93 настоящего Федерального закона), статьей 111 (в случае определения в соответствии с частью 1 статьи 111 настоящего Федерального закона особенностей, предусматривающих неразмещение информации и документов в единой информационной системе, на официальном сайте при определении поставщика (подрядчика, исполнителя) и статьей 111.1 настоящего Федерального закона, такое решение передается лицу, имеющему право действовать от имени заказчика, лично под расписку или направляется заказчику по почте заказным письмом с уведомлением о вручении по адресу заказчика, указанному в контракте. Выполнение поставщиком (подрядчиком, исполнителем) требований настоящей части считается надлежащим уведомлением заказчика об одностороннем отказе от исполнения контракта. Датой такого надлежащего уведомления считается:
1) дата, указанная лицом, имеющим право действовать от имени заказчика, в расписке о получении решения об одностороннем отказе от исполнения контракта (в случае передачи такого решения лицу, имеющему право действовать от имени заказчика, лично под расписку);
2) дата получения поставщиком (подрядчиком, исполнителем) подтверждения о вручении заказчику заказного письма, предусмотренного настоящей частью, либо дата получения поставщиком (подрядчиком, исполнителем) информации об отсутствии заказчика по адресу, указанному в контракте, информации о возврате такого письма по истечении срока хранения (в случае направления решения об одностороннем отказе от исполнения контракта заказным письмом).', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst3024', '1ffbeaaa82141d3126cc9b83315fa42a253150c2986ce24209ef54c1492c7c8b', NULL),
    ('44fz/95/21@2026-11-25:079431fde9d4', '44fz/95/21', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '21. Решение поставщика (подрядчика, исполнителя) об одностороннем отказе от исполнения контракта вступает в силу и контракт считается расторгнутым через десять дней с даты надлежащего уведомления поставщиком (подрядчиком, исполнителем) заказчика об одностороннем отказе от исполнения контракта.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101338', '079431fde9d4c077535b107867db2fda332adc665b0de409b1195933bf87f831', NULL),
    ('44fz/95/22@2026-11-25:9cfa06b22b03', '44fz/95/22', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '22. Поставщик (подрядчик, исполнитель) обязан отменить не вступившее в силу решение об одностороннем отказе от исполнения контракта, если в течение десятидневного срока с даты надлежащего уведомления заказчика о принятом решении об одностороннем отказе от исполнения контракта устранены нарушения условий контракта, послужившие основанием для принятия указанного решения.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst101339', '9cfa06b22b0337a96b739bf28fedfb538797c84577a67f18d21c15f436f68812', NULL),
    ('44fz/95/22.1@2026-11-25:15c535f4b8fa', '44fz/95/22.1', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '22.1. В случае отмены поставщиком (подрядчиком, исполнителем) в соответствии с настоящим Федеральным законом не вступившего в силу решения об одностороннем отказе от исполнения контракта, размещенного в единой информационной системе в соответствии с частью 20.1 настоящей статьи, поставщик (подрядчик, исполнитель) не позднее одного дня, следующего за днем такой отмены, формирует с использованием единой информационной системы извещение об отмене решения об одностороннем отказе от исполнения контракта, подписывает его усиленной электронной подписью лица, имеющего право действовать от имени поставщика (подрядчика, исполнителя), и размещает такое извещение в единой информационной системе. В случаях, предусмотренных частью 5 статьи 103 настоящего Федерального закона, такое извещение не размещается на официальном сайте.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/f4823c3311874efd0ecdfa668c9705968edbc47c/#dst3027', '15c535f4b8fab7abf5c3e1ee3e77f572d2961db93ccbff02a7d455a7773d20f9', NULL),
    ('44fz/112/65.1@2026-11-25:de53562317c2', '44fz/112/65.1', '2026-08-04', 'edition', NULL, '2026-10-01', '2026-11-25', '65.1. По соглашению сторон допускается изменение существенных условий контракта, заключенного до 1 января 2027 года, если при исполнении такого контракта возникли независящие от сторон контракта обстоятельства, влекущие невозможность его исполнения. Предусмотренное настоящей частью изменение осуществляется с соблюдением положений частей 1.3 - 1.6 статьи 95 настоящего Федерального закона на основании решения Правительства Российской Федерации, высшего исполнительного органа субъекта Российской Федерации, местной администрации при осуществлении закупки для федеральных нужд, нужд субъекта Российской Федерации, муниципальных нужд соответственно.', 'https://www.consultant.ru/document/cons_doc_LAW_144624/14979ba8493a52d2aa29ae0930046cf6f81caea0/#dst12008', 'de53562317c29db61b760f659c0562b15c7cd621376368db09d10c279b40bd69', 'Проверить дату заключения, независимые от сторон обстоятельства, решение компетентного органа и применимую редакцию.'),
    ('279fz/2/1@2026-11-25:6d2feab86064', '279fz/2/1', '2026-08-04', 'original', NULL, NULL, '2026-11-25', '1. Настоящий Федеральный закон вступает в силу с 1 октября 2026 года, за исключением положений, для которых настоящей статьей установлены иные сроки вступления их в силу.', 'https://www.consultant.ru/document/cons_doc_LAW_540928/b004fed0b70d0f223e4a81f8ad6cd92af90a7e3b/#dst100044', '6d2feab860647b6999ff97c5c9ffd01cffc58962f4ec9f57bf3a31d37bdab61e', NULL),
    ('279fz/2/2@2026-11-25:f7cbaac327dd', '279fz/2/2', '2026-08-04', 'original', NULL, NULL, '2026-11-25', '2. Подпункт "в" пункта 5 статьи 1 настоящего Федерального закона вступает в силу со дня официального опубликования настоящего Федерального закона.', 'https://www.consultant.ru/document/cons_doc_LAW_540928/b004fed0b70d0f223e4a81f8ad6cd92af90a7e3b/#dst100045', 'f7cbaac327dd7cfd65a65bd639295e92de40f52103d5c995f677e044afffbd19', NULL),
    ('279fz/2/3@2026-11-25:60ce07eb757f', '279fz/2/3', '2026-08-04', 'original', NULL, NULL, '2026-11-25', '3. Пункты 2, 4, подпункт "б" пункта 5, подпункт "б" пункта 7, подпункт "а" пункта 8 статьи 1 настоящего Федерального закона вступают в силу с 1 января 2027 года.', 'https://www.consultant.ru/document/cons_doc_LAW_540928/b004fed0b70d0f223e4a81f8ad6cd92af90a7e3b/#dst100046', '60ce07eb757f5b785ed11a428fe01754d0a5b7bb966d4a844a41d418ad3e95e4', NULL),
    ('279fz/2/4@2026-11-25:7e1b0c9cf645', '279fz/2/4', '2026-08-04', 'original', NULL, NULL, '2026-11-25', '4. Положения пункта 1.2 части 1 статьи 95 Федерального закона от 5 апреля 2013 года N 44-ФЗ "О контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд" (в редакции настоящего Федерального закона), касающиеся увеличения или уменьшения количества поставляемого товара, цены контракта не более чем на тридцать процентов, если предметом контракта является поставка лекарственных препаратов, медицинских изделий, расходных материалов к ним, применяются с 1 января 2027 года.', 'https://www.consultant.ru/document/cons_doc_LAW_540928/b004fed0b70d0f223e4a81f8ad6cd92af90a7e3b/#dst100047', '7e1b0c9cf645745aa07966c4a9ff5ba107339f78d830622ef7c96efd4d2c6e7b', NULL),
    ('223fz/2/1@2026-11-25:69d5dc0e9dde', '223fz/2/1', '2024-08-08', 'edition', NULL, '2025-01-01', '2026-11-25', '1. При закупке товаров, работ, услуг заказчики руководствуются Конституцией Российской Федерации, Гражданским кодексом Российской Федерации, настоящим Федеральным законом, другими федеральными законами и иными нормативными правовыми актами Российской Федерации, а также принятыми в соответствии с ними и утвержденными с учетом положений части 3 настоящей статьи правовыми актами, регламентирующими правила закупки (далее - положение о закупке).', 'https://www.consultant.ru/document/cons_doc_LAW_116964/fa59dfcdcfd8c5c80928d33fa840280273464c74/#dst100024', '69d5dc0e9dde810b7f5c1094c0fb603f146ed62a212e61530ac2dc8095bfef91', NULL),
    ('223fz/2/2@2026-11-25:0c25a1c43394', '223fz/2/2', '2024-08-08', 'edition', NULL, '2025-01-01', '2026-11-25', '2. Положение о закупке является документом, который регламентирует закупочную деятельность заказчика и должен содержать требования к закупке, в том числе порядок определения и обоснования начальной (максимальной) цены договора, цены договора, заключаемого с единственным поставщиком (исполнителем, подрядчиком), включая порядок определения формулы цены, устанавливающей правила расчета сумм, подлежащих уплате заказчиком поставщику (исполнителю, подрядчику) в ходе исполнения договора (далее - формула цены), определения и обоснования цены единицы товара, работы, услуги, определения максимального значения цены договора, порядок подготовки и осуществления закупок способами, указанными в частях 3.1 и 3.2 статьи 3 настоящего Федерального закона, порядок и условия их применения, порядок заключения и исполнения договоров, а также иные связанные с обеспечением закупки положения.', 'https://www.consultant.ru/document/cons_doc_LAW_116964/fa59dfcdcfd8c5c80928d33fa840280273464c74/#dst100025', '0c25a1c4339449092b9973b932171328bd585ee1080870c9464377e6d9aac250', NULL),
    ('223fz/4/1@2026-11-25:a11c3a6f7899', '223fz/4/1', '2024-08-08', 'edition', NULL, '2025-01-01', '2026-11-25', '1. Положение о закупке, изменения, вносимые в указанное положение, подлежат обязательному размещению в единой информационной системе не позднее чем в течение пятнадцати дней со дня утверждения.', 'https://www.consultant.ru/document/cons_doc_LAW_116964/441d00be62e3224cdc0514cffaf2a26b5b40a1c7/#dst100051', 'a11c3a6f7899fb72a2b3e36e0c65a4165d5aacecce6a26a456bfc4e80b124e55', NULL),
    ('223fz/4/5@2026-11-25:f0ec8a64baa6', '223fz/4/5', '2024-08-08', 'edition', NULL, '2025-01-01', '2026-11-25', '5. При осуществлении закупки в единой информационной системе, на официальном сайте, за исключением случаев, предусмотренных настоящим Федеральным законом, размещаются извещение об осуществлении конкурентной закупки, документация о конкурентной закупке, проект договора, являющийся неотъемлемой частью извещения об осуществлении конкурентной закупки и документации о конкурентной закупке, изменения, внесенные в такие извещение и документацию, разъяснения такой документации, протоколы, составляемые при осуществлении закупки, итоговый протокол, иная дополнительная информация, предусмотренная в соответствии с частью 6 настоящей статьи (далее - информация о закупке). В случае, если при заключении и исполнении договора изменяются количество, объем, цена закупаемых товаров, работ, услуг или сроки исполнения договора по сравнению с указанными в итоговом протоколе, не позднее чем в течение десяти дней со дня внесения изменений в договор в единой информационной системе размещается информация об изменении договора с указанием измененных условий. При закупке у единственного поставщика (исполнителя, подрядчика) информация о такой закупке, предусмотренная настоящей частью, может быть размещена заказчиком в единой информационной системе в случае, если это предусмотрено положением о закупке.', 'https://www.consultant.ru/document/cons_doc_LAW_116964/441d00be62e3224cdc0514cffaf2a26b5b40a1c7/#dst100055', 'f0ec8a64baa67f80852aa91cde748a0dbc29608070d0bc05d4880236d1284a4b', NULL),
    ('vs223/16@2026-11-25:2d1e8e8d187a', 'vs223/16', '2018-05-16', 'original', NULL, NULL, '2026-11-25', '16. Изменение договора, заключенного по правилам Закона о закупках, которое повлияет на его условия по сравнению с условиями документации о закупке, имевшими существенное значение для формирования заявок, определения победителя, определения цены договора, не допускается.
Участник аукциона обратился в арбитражный суд с заявлением к государственному унитарному предприятию и обществу - победителю аукциона - о признании недействительным дополнительного соглашения к договору на поставку топочного мазута.
Решением арбитражного суда первой инстанции, оставленным без изменения постановлением суда апелляционной инстанции, исковые требования удовлетворены.
Судами принято во внимание, что частью 5 статьи 4 Закона о закупках предусмотрено право сторон на изменение договора по определению объема, цены закупаемых товаров, работ, услуг или сроков исполнения договора. Подобные изменения возможны при условии обеспечения информационной открытости таких изменений путем размещения соответствующей информации на официальном сайте в течение десяти дней со дня внесения изменений в договор. Целью предоставления права изменять договор являются рациональное использование денежных средств и эффективное участие предусмотренных частью 2 статьи 1 Закона о закупках субъектов, а требование о размещении информации соотносится с общим принципом обеспечения гласности и прозрачности закупки.
Дополнительно судами указано, что изменение условий договора с победителем допускается по основаниям, определенным гражданским законодательством, что само по себе не может свидетельствовать о нарушении требований частей 1 и 2 статьи 17 Закона о защите конкуренции; недобросовестность действий заказчика и победителя истцом не доказана.
Вместе с тем судами установлено, что на основании дополнительного соглашения многократно увеличена цена договора. Такое изменение является произвольным, направлено на нивелирование условий проведенного аукциона (в частности, основной договор содержал условие о неизменности цены договора на протяжении всего срока его действия), не соответствует принципам осуществления закупок (эффективности, обеспечения конкуренции, недопущения злоупотреблений, в том числе коррупции), нарушает требования пункта 8 статьи 448 ГК РФ (в редакции, действовавшей на момент рассмотрения спора, до 01.06.2018) о недопущении изменения договора, которое влияет на его условия, имевшие существенное значение для определения цены на торгах.', 'https://www.garant.ru/products/ipo/prime/doc/71843112/', '2d1e8e8d187a1567076b42fbf69ef7e1b121c5b8f7575b1f93f8c13a358d1243', NULL),
    ('gk1/310/1@2026-11-25:923643808958', 'gk1/310/1', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '1. Односторонний отказ от исполнения обязательства и одностороннее изменение его условий не допускаются, за исключением случаев, предусмотренных настоящим Кодексом, другими законами или иными правовыми актами.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/33c65ab7522b599d12e61cc848aebcd09e651f9c/#dst10514', '92364380895847eeeef2f18838a4da15f22124b9b7ef5121829cc6750e1c92fb', NULL),
    ('gk1/310/2@2026-11-25:1536633aa559', 'gk1/310/2', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '2. Одностороннее изменение условий обязательства, связанного с осуществлением всеми его сторонами предпринимательской деятельности, или односторонний отказ от исполнения этого обязательства допускается в случаях, предусмотренных настоящим Кодексом, другими законами, иными правовыми актами или договором.
В случае, если исполнение обязательства связано с осуществлением предпринимательской деятельности не всеми его сторонами, право на одностороннее изменение его условий или отказ от исполнения обязательства может быть предоставлено договором лишь стороне, не осуществляющей предпринимательской деятельности, за исключением случаев, когда законом или иным правовым актом предусмотрена возможность предоставления договором такого права другой стороне.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/33c65ab7522b599d12e61cc848aebcd09e651f9c/#dst10515', '1536633aa559d4c7540743324fc568e922922b6ace18470657ccc5cbba0ae28c', NULL),
    ('gk1/310/3@2026-11-25:4cb71ea3ab02', 'gk1/310/3', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '3. Предусмотренное настоящим Кодексом, другим законом, иным правовым актом или договором право на односторонний отказ от исполнения обязательства, связанного с осуществлением его сторонами предпринимательской деятельности, или на одностороннее изменение условий такого обязательства может быть обусловлено по соглашению сторон необходимостью выплаты определенной денежной суммы другой стороне обязательства.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/33c65ab7522b599d12e61cc848aebcd09e651f9c/#dst10517', '4cb71ea3ab02baefaeb420a6211dc395180a49c4bb67613e7ca4f925c7c585ce', NULL),
    ('gk1/450.1/1@2026-11-25:5f943bfd5a89', 'gk1/450.1/1', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '1. Предоставленное настоящим Кодексом, другими законами, иными правовыми актами или договором право на односторонний отказ от договора (исполнения договора) (статья 310) может быть осуществлено управомоченной стороной путем уведомления другой стороны об отказе от договора (исполнения договора). Договор прекращается с момента получения данного уведомления, если иное не предусмотрено настоящим Кодексом, другими законами, иными правовыми актами или договором.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/5a4f710216fdced777b2d5a1335560ccdefe66fd/#dst10842', '5f943bfd5a8990e63cf2b49faeb029e48c013d90a132fecad7da61687d534698', NULL),
    ('gk1/450.1/2@2026-11-25:f1e9f8723279', 'gk1/450.1/2', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '2. В случае одностороннего отказа от договора (исполнения договора) полностью или частично, если такой отказ допускается, договор считается расторгнутым или измененным.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/5a4f710216fdced777b2d5a1335560ccdefe66fd/#dst10843', 'f1e9f872327919095fd6b7007fa30441376a7f435eb3b211d4aa87ac7f4fa1e4', NULL),
    ('gk1/450.1/3@2026-11-25:313f849cc4cb', 'gk1/450.1/3', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '3. В случае отсутствия у одной из сторон договора лицензии на осуществление деятельности или членства в саморегулируемой организации, необходимых для исполнения обязательства по договору, другая сторона вправе отказаться от договора (исполнения договора) и потребовать возмещения убытков.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/5a4f710216fdced777b2d5a1335560ccdefe66fd/#dst10844', '313f849cc4cbe2b509903f1dfbf4ec77d093e120147a3f29a62ff4efa8d740ea', NULL),
    ('gk1/450.1/4@2026-11-25:72f2d7b74518', 'gk1/450.1/4', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '4. Сторона, которой настоящим Кодексом, другими законами, иными правовыми актами или договором предоставлено право на отказ от договора (исполнения договора), должна при осуществлении этого права действовать добросовестно и разумно в пределах, предусмотренных настоящим Кодексом, другими законами, иными правовыми актами или договором.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/5a4f710216fdced777b2d5a1335560ccdefe66fd/#dst10845', '72f2d7b745181b65bffabdf01342a24e563cb2408b78ac10f077bd7e19db25e8', NULL),
    ('gk1/450.1/5@2026-11-25:1c95949d5d05', 'gk1/450.1/5', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '5. В случаях, если при наличии оснований для отказа от договора (исполнения договора) сторона, имеющая право на такой отказ, подтверждает действие договора, в том числе путем принятия от другой стороны предложенного последней исполнения обязательства, последующий отказ по тем же основаниям не допускается.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/5a4f710216fdced777b2d5a1335560ccdefe66fd/#dst10846', '1c95949d5d05d3270a5c02061fef4d870d04519535879fbbee74f591a6108ce4', NULL),
    ('gk1/450.1/6@2026-11-25:a6b7796aa6a1', 'gk1/450.1/6', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '6. Если иное не предусмотрено настоящим Кодексом, другими законами, иными правовыми актами или договором, в случаях, когда сторона, осуществляющая предпринимательскую деятельность, при наступлении обстоятельств, предусмотренных настоящим Кодексом, другими законами, иными правовыми актами или договором и служащих основанием для осуществления определенного права по договору, заявляет отказ от осуществления этого права, в последующем осуществление этого права по тем же основаниям не допускается, за исключением случаев, когда аналогичные обстоятельства наступили вновь.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/5a4f710216fdced777b2d5a1335560ccdefe66fd/#dst10847', 'a6b7796aa6a131107e38fe2400079a18d4de3349a034f84e55c8f16ccd661a8e', NULL),
    ('gk1/450.1/7@2026-11-25:5cbe6e71d2bd', 'gk1/450.1/7', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '7. В случаях, установленных настоящим Кодексом, другими законами, иными правовыми актами или договором, правила пункта 6 настоящей статьи применяются при неосуществлении определенного права в срок, предусмотренный настоящим Кодексом, другими законами, иными правовыми актами или договором.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/5a4f710216fdced777b2d5a1335560ccdefe66fd/#dst10848', '5cbe6e71d2bdb0254fc6eb18f8db9c6829fb4401335ab1c9a9b15caa0539e1d9', NULL),
    ('gk2/523/1@2026-11-25:7ef0d3e701da', 'gk2/523/1', '2025-06-24', 'edition', '2026-06-09', NULL, '2026-11-25', '1. Односторонний отказ от исполнения договора поставки (полностью или частично) или одностороннее его изменение допускаются в случае существенного нарушения договора одной из сторон (абзац четвертый пункта 2 статьи 450).', 'https://www.consultant.ru/document/cons_doc_LAW_9027/c0a62e133ab20f06d1da531c5cbcfc4056478f55/#dst100318', '7ef0d3e701da70ad0c9b6d452f2bc92461ddecefb56432b687f235c9115a09a3', NULL),
    ('gk2/523/2@2026-11-25:9d338a502789', 'gk2/523/2', '2025-06-24', 'edition', '2026-06-09', NULL, '2026-11-25', '2. Нарушение договора поставки поставщиком предполагается существенным в случаях:
поставки товаров ненадлежащего качества с недостатками, которые не могут быть устранены в приемлемый для покупателя срок;
неоднократного нарушения сроков поставки товаров.', 'https://www.consultant.ru/document/cons_doc_LAW_9027/c0a62e133ab20f06d1da531c5cbcfc4056478f55/#dst100319', '9d338a502789934cb4d27e6c1199f70b58847225576a05bc9d51408df55f2180', NULL),
    ('gk2/523/3@2026-11-25:f5c6f7fa3783', 'gk2/523/3', '2025-06-24', 'edition', '2026-06-09', NULL, '2026-11-25', '3. Нарушение договора поставки покупателем предполагается существенным в случаях:
неоднократного нарушения сроков оплаты товаров;
неоднократной невыборки товаров.', 'https://www.consultant.ru/document/cons_doc_LAW_9027/c0a62e133ab20f06d1da531c5cbcfc4056478f55/#dst100322', 'f5c6f7fa37834f63615105eac604f43323b7bf7171fd97d02ebb2635ff15c7af', NULL),
    ('gk2/523/4@2026-11-25:f12048afa4fb', 'gk2/523/4', '2025-06-24', 'edition', '2026-06-09', NULL, '2026-11-25', '4. Договор поставки считается измененным или расторгнутым с момента получения одной стороной уведомления другой стороны об одностороннем отказе от исполнения договора полностью или частично, если иной срок расторжения или изменения договора не предусмотрен в уведомлении либо не определен соглашением сторон.', 'https://www.consultant.ru/document/cons_doc_LAW_9027/c0a62e133ab20f06d1da531c5cbcfc4056478f55/#dst100325', 'f12048afa4fbda3f7e1ba2f3c3cb720dd2a0e5af4ae7fa684e9252fa172e9b13', NULL),
    ('gk2/782/1@2026-11-25:27150daab1fc', 'gk2/782/1', '2025-06-24', 'edition', '2026-06-09', NULL, '2026-11-25', '1. Заказчик вправе отказаться от исполнения договора возмездного оказания услуг при условии оплаты исполнителю фактически понесенных им расходов.', 'https://www.consultant.ru/document/cons_doc_LAW_9027/e21d6a868cf614117afa2f93877215e487cd4aee/#dst101337', '27150daab1fc1d3f6e427c9cf11400080a9e8bdf97fdfe8ad1b50ce022dfb3b6', NULL),
    ('gk2/782/2@2026-11-25:c2390ab0ea3c', 'gk2/782/2', '2025-06-24', 'edition', '2026-06-09', NULL, '2026-11-25', '2. Исполнитель вправе отказаться от исполнения обязательств по договору возмездного оказания услуг лишь при условии полного возмещения заказчику убытков.', 'https://www.consultant.ru/document/cons_doc_LAW_9027/e21d6a868cf614117afa2f93877215e487cd4aee/#dst101338', 'c2390ab0ea3c324dde03983db25c5b16b43e680dc018788944aaaf8155e85ccd', NULL),
    ('gk2/717@2026-11-25:c8eba1c60235', 'gk2/717', '2025-06-24', 'edition', '2026-06-09', NULL, '2026-11-25', 'ГК РФ Статья 717. Отказ заказчика от исполнения договора подряда
Если иное не предусмотрено договором подряда, заказчик может в любое время до сдачи ему результата работы отказаться от исполнения договора, уплатив подрядчику часть установленной цены пропорционально части работы, выполненной до получения извещения об отказе заказчика от исполнения договора. Заказчик также обязан возместить подрядчику убытки, причиненные прекращением договора подряда, в пределах разницы между ценой, определенной за всю работу, и частью цены, выплаченной за выполненную работу.', 'https://www.consultant.ru/document/cons_doc_LAW_9027/cc2aa4a0762dd07bb86c13ab9666796f236ec336/#dst101088', 'c8eba1c60235a87c1753d7bca1c5c44e66c2f9099756bb393aa0f33889ef05ec', NULL),
    ('gk2/463/1@2026-11-25:bd87dcc25053', 'gk2/463/1', '2025-06-24', 'edition', '2026-06-09', NULL, '2026-11-25', '1. Если продавец отказывается передать покупателю проданный товар, покупатель вправе отказаться от исполнения договора купли-продажи.', 'https://www.consultant.ru/document/cons_doc_LAW_9027/2eae504a3bae998d6417e096544bb0d80f1f7650/#dst100048', 'bd87dcc25053343eeef62e8900177451d6797d5516bc96d2b4d047d7d77f5ba8', NULL),
    ('gk2/475/2@2026-11-25:e5d77c70fb79', 'gk2/475/2', '2025-06-24', 'edition', '2026-06-09', NULL, '2026-11-25', '2. В случае существенного нарушения требований к качеству товара (обнаружения неустранимых недостатков, недостатков, которые не могут быть устранены без несоразмерных расходов или затрат времени, или выявляются неоднократно, либо проявляются вновь после их устранения, и других подобных недостатков) покупатель вправе по своему выбору:
отказаться от исполнения договора купли-продажи и потребовать возврата уплаченной за товар денежной суммы;
потребовать замены товара ненадлежащего качества товаром, соответствующим договору.', 'https://www.consultant.ru/document/cons_doc_LAW_9027/17c385541834fe9a0d0996c1da3f0df8816438d0/#dst100107', 'e5d77c70fb797a98ce5ebc1f438684205c61dd272b0c0f32295428a43489972c', NULL),
    ('gk2/480/2@2026-11-25:cf7b28b474c1', 'gk2/480/2', '2025-06-24', 'edition', '2026-06-09', NULL, '2026-11-25', '2. Если продавец в разумный срок не выполнил требования покупателя о доукомплектовании товара, покупатель вправе по своему выбору:
потребовать замены некомплектного товара на комплектный;
отказаться от исполнения договора купли-продажи и потребовать возврата уплаченной денежной суммы.', 'https://www.consultant.ru/document/cons_doc_LAW_9027/a822439dadeeaeaa5de022bddcc3972e6ff9731f/#dst100134', 'cf7b28b474c11343321fb55bd5872af5beebd82cf4751bc488d1fd46d023f7fa', NULL),
    ('gk1/431.2/2@2026-11-25:956c3ae3cb30', 'gk1/431.2/2', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '2. Сторона, полагавшаяся на недостоверные заверения контрагента, имеющие для нее существенное значение, наряду с требованием о возмещении убытков или взыскании неустойки также вправе отказаться от договора, если иное не предусмотрено соглашением сторон.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/52b8ddfd2dcdeea14164157401daf099e5e09adb/#dst10772', '956c3ae3cb30f5ef39e160886ce47cd1a6550fe5aec292fddabee87ce0f7e5c6', NULL),
    ('gk1/422/1@2026-11-25:3c53b834cb3f', 'gk1/422/1', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '1. Договор должен соответствовать обязательным для сторон правилам, установленным законом и иными правовыми актами (императивным нормам), действующим в момент его заключения.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/478c38e91f6a68f9b7fa064f292dda8bf3049359/#dst101998', '3c53b834cb3f94fc64823b78b92c258168b0a93e12bfd110e5389ca423a3143c', NULL),
    ('gk1/422/2@2026-11-25:d70a0aa58b17', 'gk1/422/2', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '2. Если после заключения договора принят закон, устанавливающий обязательные для сторон правила иные, чем те, которые действовали при заключении договора, условия заключенного договора сохраняют силу, кроме случаев, когда в законе установлено, что его действие распространяется на отношения, возникшие из ранее заключенных договоров.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/478c38e91f6a68f9b7fa064f292dda8bf3049359/#dst101999', 'd70a0aa58b1717f6df5001672187a5ef759079ada3a70f28c81cf2bf9fe7f2be', NULL),
    ('gk1/425/3@2026-11-25:334ae7697d17', 'gk1/425/3', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '3. Законом или договором может быть предусмотрено, что окончание срока действия договора влечет прекращение обязательств сторон по договору.
Договор, в котором отсутствует такое условие, признается действующим до определенного в нем момента окончания исполнения сторонами обязательства.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/37fc094a92a4dfb5449055dff0815a76ecad5de3/#dst102012', '334ae7697d17a8deb470b9ae7dc789befa521591e3df13f3bc7041715515a5e5', NULL),
    ('gk1/425/4@2026-11-25:1f260ac4eb70', 'gk1/425/4', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '4. Окончание срока действия договора не освобождает стороны от ответственности за его нарушение.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/37fc094a92a4dfb5449055dff0815a76ecad5de3/#dst102014', '1f260ac4eb70aaeaaa5e441e87e790b71a39c2049996566c68bba68e7a252262', NULL),
    ('gk1/450/1@2026-11-25:6352d811874a', 'gk1/450/1', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '1. Изменение и расторжение договора возможны по соглашению сторон, если иное не предусмотрено настоящим Кодексом, другими законами или договором.
Многосторонним договором, исполнение которого связано с осуществлением всеми его сторонами предпринимательской деятельности, может быть предусмотрена возможность изменения или расторжения такого договора по соглашению как всех, так и большинства лиц, участвующих в указанном договоре, если иное не установлено законом. В указанном в настоящем абзаце договоре может быть предусмотрен порядок определения такого большинства.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/c231822b9f355b8c760b3389e80269f0d987870e/#dst102127', '6352d811874ad38215180b25cfab46f916f31c15eff1d2eb5306281e4b58cbf2', NULL),
    ('gk1/452/1@2026-11-25:b7805ecea095', 'gk1/452/1', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '1. Соглашение об изменении или о расторжении договора совершается в той же форме, что и договор, если из закона, иных правовых актов, договора или обычаев не вытекает иное.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/ca10f0c19da23330c9d92dacb11df0c92444bca3/#dst102144', 'b7805ecea09587cf17b7f31e9007c250e39b97df74909c6ebaeb919884f5393a', NULL),
    ('gk1/330/1@2026-11-25:471c1a120089', 'gk1/330/1', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '1. Неустойкой (штрафом, пеней) признается определенная законом или договором денежная сумма, которую должник обязан уплатить кредитору в случае неисполнения или ненадлежащего исполнения обязательства, в частности в случае просрочки исполнения. По требованию об уплате неустойки кредитор не обязан доказывать причинение ему убытков.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/b4e192e502ea85e2cf31e682d6dbd8ad395a5012/#dst101619', '471c1a120089be7dcc61c1de148f73b096839e514dea25ad2e95d90415c5bf40', NULL),
    ('gk1/330/2@2026-11-25:7b4dfbc93916', 'gk1/330/2', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '2. Кредитор не вправе требовать уплаты неустойки, если должник не несет ответственности за неисполнение или ненадлежащее исполнение обязательства.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/b4e192e502ea85e2cf31e682d6dbd8ad395a5012/#dst101620', '7b4dfbc93916a6f7967f51cfa3afedf82c42334b2b0774578bb1d79a8c8fcd98', NULL),
    ('gk1/331@2026-11-25:c50b820d18d7', 'gk1/331', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', 'ГК РФ Статья 331. Форма соглашения о неустойке
Соглашение о неустойке должно быть совершено в письменной форме независимо от формы основного обязательства.
Несоблюдение письменной формы влечет недействительность соглашения о неустойке.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/8b9cd370b5bdf76bb10656e92ffa114d6231aa3e/#dst101621', 'c50b820d18d7fbd28b11f3022f25dca436e7185a5d46470d4bb3726f273d7499', NULL),
    ('gk1/332/1@2026-11-25:44329e1dbc32', 'gk1/332/1', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '1. Кредитор вправе требовать уплаты неустойки, определенной законом (законной неустойки), независимо от того, предусмотрена ли обязанность ее уплаты соглашением сторон.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/4b864750666b6860b4164c46089a1fa9a49ab494/#dst101625', '44329e1dbc3238544265e02f69d9c9bd6684eadbb8bceda51a4ce0d4b2812e20', NULL),
    ('gk1/332/2@2026-11-25:6c1cbca2dbbd', 'gk1/332/2', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '2. Размер законной неустойки может быть увеличен соглашением сторон, если закон этого не запрещает.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/4b864750666b6860b4164c46089a1fa9a49ab494/#dst101626', '6c1cbca2dbbde8abf58f0e742296c81a65c76f0c4702d9d39167ef507013b823', NULL),
    ('gk1/333/1@2026-11-25:1841793bd64c', 'gk1/333/1', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '1. Если подлежащая уплате неустойка явно несоразмерна последствиям нарушения обязательства, суд вправе уменьшить неустойку. Если обязательство нарушено лицом, осуществляющим предпринимательскую деятельность, суд вправе уменьшить неустойку при условии заявления должника о таком уменьшении.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/f9732de88783800811973b3a13ef5112de0b5321/#dst101628', '1841793bd64c42a58347304712719f4f7beaa21b2555a66c38a6f94051a0d353', NULL),
    ('gk1/333/2@2026-11-25:d8ce0212455b', 'gk1/333/2', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '2. Уменьшение неустойки, определенной договором и подлежащей уплате лицом, осуществляющим предпринимательскую деятельность, допускается в исключительных случаях, если будет доказано, что взыскание неустойки в предусмотренном договором размере может привести к получению кредитором необоснованной выгоды.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/f9732de88783800811973b3a13ef5112de0b5321/#dst10575', 'd8ce0212455bf9acf3320c78f2a3f843789f4718466c763efd7cb1688938e832', NULL),
    ('gk1/333/3@2026-11-25:96a042aa5709', 'gk1/333/3', '2026-06-10', 'edition', '2026-10-22', NULL, '2026-11-25', '3. Правила настоящей статьи не затрагивают право должника на уменьшение размера его ответственности на основании статьи 404 настоящего Кодекса и право кредитора на возмещение убытков в случаях, предусмотренных статьей 394 настоящего Кодекса.', 'https://www.consultant.ru/document/cons_doc_LAW_5142/f9732de88783800811973b3a13ef5112de0b5321/#dst101629', '96a042aa5709d4fb0df31b4aeda2c746dfe998fef5d29bfbfde52c411d7dd30f', NULL),
    ('pp1042/decree/3@2026-11-25:d2035968b5c7', 'pp1042/decree/3', '2019-08-02', 'edition', NULL, NULL, '2026-11-25', '3. Настоящее постановление применяется к отношениям, связанным с осуществлением закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд, извещения об осуществлении которых размещены в единой информационной системе в сфере закупок либо приглашения принять участие в которых направлены после дня вступления в силу настоящего постановления.', 'https://www.consultant.ru/document/cons_doc_LAW_227100/92d969e26a4326c5d02fa79b8f9cf4994ee5633b/#dst100009', 'd2035968b5c74d4766ced7d8096698bf76fe94145293b0178dba3c4cc9ebf874', NULL),
    ('pp1042/rules/1@2026-11-25:716f7cf8dc01', 'pp1042/rules/1', '2019-08-02', 'edition', NULL, NULL, '2026-11-25', '1. Настоящие Правила устанавливают порядок определения в контракте размера штрафа, начисляемого за ненадлежащее исполнение заказчиком обязательств, предусмотренных контрактом, за исключением просрочки исполнения обязательств, предусмотренных контрактом и размера штрафа, начисляемого за неисполнение или ненадлежащее исполнение поставщиком (подрядчиком, исполнителем) обязательств, предусмотренных контрактом, за исключением просрочки исполнения обязательств (в том числе гарантийного обязательства), предусмотренных контрактом (далее - штраф).', 'https://www.consultant.ru/document/cons_doc_LAW_227100/c68b95fe21383d322ccb40aefb0407782166052a/#dst100017', '716f7cf8dc014364b5de3187177d97d1ea7af022148f92c8651b17d4b7802f37', NULL),
    ('pp1042/rules/2@2026-11-25:8a7f0199942e', 'pp1042/rules/2', '2019-08-02', 'edition', NULL, NULL, '2026-11-25', '2. Размер штрафа устанавливается контрактом в соответствии с пунктами 3 - 9 настоящих Правил, за исключением случая, предусмотренного пунктом 13 настоящих Правил, в том числе рассчитывается как процент цены контракта, или в случае, если контрактом предусмотрены этапы исполнения контракта, как процент этапа исполнения контракта (далее - цена контракта (этапа)).', 'https://www.consultant.ru/document/cons_doc_LAW_227100/c68b95fe21383d322ccb40aefb0407782166052a/#dst100018', '8a7f0199942e4c3159b8148b918deec45b1ba45921b7ee847119d945ca5f8b4f', NULL),
    ('pp1042/rules/3@2026-11-25:5e0081122d6e', 'pp1042/rules/3', '2019-08-02', 'edition', NULL, NULL, '2026-11-25', '3. За каждый факт неисполнения или ненадлежащего исполнения поставщиком (подрядчиком, исполнителем) обязательств, предусмотренных контрактом, за исключением просрочки исполнения обязательств (в том числе гарантийного обязательства), предусмотренных контрактом, размер штрафа устанавливается в следующем порядке (за исключением случаев, предусмотренных пунктами 4 - 8 настоящих Правил):
а) 10 процентов цены контракта (этапа) в случае, если цена контракта (этапа) не превышает 3 млн. рублей;
б) 5 процентов цены контракта (этапа) в случае, если цена контракта (этапа) составляет от 3 млн. рублей до 50 млн. рублей (включительно);
в) 1 процент цены контракта (этапа) в случае, если цена контракта (этапа) составляет от 50 млн. рублей до 100 млн. рублей (включительно);
г) 0,5 процента цены контракта (этапа) в случае, если цена контракта (этапа) составляет от 100 млн. рублей до 500 млн. рублей (включительно);
д) 0,4 процента цены контракта (этапа) в случае, если цена контракта (этапа) составляет от 500 млн. рублей до 1 млрд. рублей (включительно);
е) 0,3 процента цены контракта (этапа) в случае, если цена контракта (этапа) составляет от 1 млрд. рублей до 2 млрд. рублей (включительно);
ж) 0,25 процента цены контракта (этапа) в случае, если цена контракта (этапа) составляет от 2 млрд. рублей до 5 млрд. рублей (включительно);
з) 0,2 процента цены контракта (этапа) в случае, если цена контракта (этапа) составляет от 5 млрд. рублей до 10 млрд. рублей (включительно);
и) 0,1 процента цены контракта (этапа) в случае, если цена контракта (этапа) превышает 10 млрд. рублей.', 'https://www.consultant.ru/document/cons_doc_LAW_227100/c68b95fe21383d322ccb40aefb0407782166052a/#dst100019', '5e0081122d6e23bff4326d53cb06958ebea2a3af4c5ca3d0b831f03dcc1f0490', NULL),
    ('pp1042/rules/4@2026-11-25:587c9c23d30f', 'pp1042/rules/4', '2019-08-02', 'edition', NULL, NULL, '2026-11-25', '4. За каждый факт неисполнения или ненадлежащего исполнения поставщиком (подрядчиком, исполнителем) обязательств, предусмотренных контрактом, заключенным по результатам определения поставщика (подрядчика, исполнителя) в соответствии с пунктом 1 части 1 статьи 30 Федерального закона "О контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд" (далее - Федеральный закон), за исключением просрочки исполнения обязательств (в том числе гарантийного обязательства), предусмотренных контрактом, размер штрафа устанавливается в размере 1 процента цены контракта (этапа), но не более 5 тыс. рублей и не менее 1 тыс. рублей.', 'https://www.consultant.ru/document/cons_doc_LAW_227100/c68b95fe21383d322ccb40aefb0407782166052a/#dst100032', '587c9c23d30fa326c288dbae773b88c15e7606ea68c9674ea53f33860bda2808', NULL),
    ('pp1042/rules/5@2026-11-25:7906fa605cae', 'pp1042/rules/5', '2019-08-02', 'edition', NULL, NULL, '2026-11-25', '5. За каждый факт неисполнения или ненадлежащего исполнения поставщиком (подрядчиком, исполнителем) обязательств, предусмотренных контрактом, заключенным с победителем закупки (или с иным участником закупки в случаях, установленных Федеральным законом), предложившим наиболее высокую цену за право заключения контракта, размер штрафа рассчитывается в порядке, установленном настоящими Правилами, за исключением просрочки исполнения обязательств (в том числе гарантийного обязательства), предусмотренных контрактом, и устанавливается в следующем порядке:
а) в случае, если цена контракта не превышает начальную (максимальную) цену контракта:
10 процентов начальной (максимальной) цены контракта, если цена контракта не превышает 3 млн. рублей;
5 процентов начальной (максимальной) цены контракта, если цена контракта составляет от 3 млн. рублей до 50 млн. рублей (включительно);
1 процент начальной (максимальной) цены контракта, если цена контракта составляет от 50 млн. рублей до 100 млн. рублей (включительно);
б) в случае, если цена контракта превышает начальную (максимальную) цену контракта:
10 процентов цены контракта, если цена контракта не превышает 3 млн. рублей;
5 процентов цены контракта, если цена контракта составляет от 3 млн. рублей до 50 млн. рублей (включительно);
1 процент цены контракта, если цена контракта составляет от 50 млн. рублей до 100 млн. рублей (включительно).', 'https://www.consultant.ru/document/cons_doc_LAW_227100/c68b95fe21383d322ccb40aefb0407782166052a/#dst100033', '7906fa605caecacbbbf1a9dfcad9abf410ea484868258c3b23df150bf4b03e85', NULL),
    ('pp1042/rules/6@2026-11-25:5fe61f23c56b', 'pp1042/rules/6', '2019-08-02', 'edition', NULL, NULL, '2026-11-25', '6. За каждый факт неисполнения или ненадлежащего исполнения поставщиком (подрядчиком, исполнителем) обязательства, предусмотренного контрактом, которое не имеет стоимостного выражения, размер штрафа устанавливается (при наличии в контракте таких обязательств) в следующем порядке:
а) 1000 рублей, если цена контракта не превышает 3 млн. рублей;
б) 5000 рублей, если цена контракта составляет от 3 млн. рублей до 50 млн. рублей (включительно);
в) 10000 рублей, если цена контракта составляет от 50 млн. рублей до 100 млн. рублей (включительно);
г) 100000 рублей, если цена контракта превышает 100 млн. рублей.', 'https://www.consultant.ru/document/cons_doc_LAW_227100/c68b95fe21383d322ccb40aefb0407782166052a/#dst100037', '5fe61f23c56b8bee72ad425b213c5af11c440854a8cc6edcc545ef2d4c566124', NULL),
    ('pp1042/rules/7@2026-11-25:707e84dcee6c', 'pp1042/rules/7', '2019-08-02', 'edition', NULL, NULL, '2026-11-25', '7. За ненадлежащее исполнение подрядчиком обязательств по выполнению видов и объемов работ по строительству, реконструкции объектов капитального строительства, которые подрядчик обязан выполнить самостоятельно без привлечения других лиц к исполнению своих обязательств по контракту, размер штрафа устанавливается в размере 5 процентов стоимости указанных работ.', 'https://www.consultant.ru/document/cons_doc_LAW_227100/c68b95fe21383d322ccb40aefb0407782166052a/#dst100042', '707e84dcee6ca1cf04e571a34b499d477a9f914405532b03762dfa5b647bfcff', NULL),
    ('pp1042/rules/8@2026-11-25:8c1e0439fc2b', 'pp1042/rules/8', '2019-08-02', 'edition', NULL, NULL, '2026-11-25', '8. В случае если в соответствии с частью 6 статьи 30 Федерального закона контрактом предусмотрено условие о гражданско-правовой ответственности поставщиков (подрядчиков, исполнителей) за неисполнение условия о привлечении к исполнению контракта субподрядчиков, соисполнителей из числа субъектов малого предпринимательства, социально ориентированных некоммерческих организаций в виде штрафа, штраф устанавливается в размере 5 процентов объема такого привлечения, установленного контрактом.', 'https://www.consultant.ru/document/cons_doc_LAW_227100/c68b95fe21383d322ccb40aefb0407782166052a/#dst100043', '8c1e0439fc2b78ea96a080966916970a1d888fc6050af12ae859d5ba3fde05ea', NULL),
    ('pp1042/rules/9@2026-11-25:dd05945a8e20', 'pp1042/rules/9', '2019-08-02', 'edition', NULL, NULL, '2026-11-25', '9. За каждый факт неисполнения заказчиком обязательств, предусмотренных контрактом, за исключением просрочки исполнения обязательств, предусмотренных контрактом, размер штрафа устанавливается в следующем порядке:
а) 1000 рублей, если цена контракта не превышает 3 млн. рублей (включительно);
б) 5000 рублей, если цена контракта составляет от 3 млн. рублей до 50 млн. рублей (включительно);
в) 10000 рублей, если цена контракта составляет от 50 млн. рублей до 100 млн. рублей (включительно);
г) 100000 рублей, если цена контракта превышает 100 млн. рублей.', 'https://www.consultant.ru/document/cons_doc_LAW_227100/c68b95fe21383d322ccb40aefb0407782166052a/#dst100044', 'dd05945a8e20e2009d116a1ba91973a378b99941946283a13c4e36745b03f298', NULL),
    ('pp1042/rules/11@2026-11-25:c1e3c698c8c3', 'pp1042/rules/11', '2019-08-02', 'edition', NULL, NULL, '2026-11-25', '11. Общая сумма начисленных штрафов за неисполнение или ненадлежащее исполнение поставщиком (подрядчиком, исполнителем) обязательств, предусмотренных контрактом, не может превышать цену контракта.', 'https://www.consultant.ru/document/cons_doc_LAW_227100/c68b95fe21383d322ccb40aefb0407782166052a/#dst100050', 'c1e3c698c8c3bc8896d52449528d4f441d8c71eed10efb9b866372d5411d2f0f', NULL),
    ('pp1042/rules/12@2026-11-25:0f5a5911fee0', 'pp1042/rules/12', '2019-08-02', 'edition', NULL, NULL, '2026-11-25', '12. Общая сумма начисленных штрафов за ненадлежащее исполнение заказчиком обязательств, предусмотренных контрактом, не может превышать цену контракта.', 'https://www.consultant.ru/document/cons_doc_LAW_227100/c68b95fe21383d322ccb40aefb0407782166052a/#dst100051', '0f5a5911fee0d9b24570e13ebbff4e05f7334ba42a8e65485f00bf69f7ce95bd', NULL),
    ('pp1042/rules/13@2026-11-25:dcf0caebe7cd', 'pp1042/rules/13', '2019-08-02', 'edition', NULL, NULL, '2026-11-25', '13. В случае если законодательством Российской Федерации установлен иной порядок начисления штрафа, чем порядок, предусмотренный настоящими Правилами, размер такого штрафа и порядок его начисления устанавливается контрактом в соответствии с законодательством Российской Федерации.', 'https://www.consultant.ru/document/cons_doc_LAW_227100/c68b95fe21383d322ccb40aefb0407782166052a/#dst23', 'dcf0caebe7cd84e935d2af7f7443f96f96f2c0323ad6e06c61567b9ce4a02879', NULL),
    ('pp1186/1@2026-11-25:9a7a90f7ea50', 'pp1186/1', '2024-09-03', 'edition', NULL, NULL, '2026-11-25', '1. Установить следующие размеры цены контракта, заключенного на срок не менее чем 3 года для обеспечения федеральных нужд, нужд субъекта Российской Федерации и на срок не менее чем 1 год для обеспечения муниципальных нужд, при которой или при превышении которой существенные условия контракта могут быть изменены в установленном порядке, в случае если выполнение контракта по независящим от сторон контракта обстоятельствам без изменения его условий невозможно:
10 млрд. рублей - для контракта, заключенного для обеспечения федеральных нужд, за исключением контрактов, предусмотренных абзацами пятым - седьмым настоящего пункта;
1 млрд. рублей - для контракта, заключенного для обеспечения нужд субъекта Российской Федерации, за исключением контрактов, предусмотренных абзацами шестым и восьмым настоящего пункта;
500 млн. рублей - для контракта, заключенного для обеспечения муниципальных нужд, за исключением контрактов, предусмотренных абзацами шестым и девятым настоящего пункта;
40 млн. рублей - для контракта, заключенного для обеспечения федеральных нужд, включающего выполнение работ по проведению клинических исследований лекарственных препаратов для медицинского применения;
100 млн. рублей - для контракта жизненного цикла;
100 млн. рублей - для контракта, заключенного для обеспечения федеральных нужд, включающего выполнение работ по геологическому изучению недр;
1 млн. рублей - для государственного контракта на выполнение работ, связанных с осуществлением регулярных перевозок пассажиров и багажа автомобильным транспортом и городским наземным электрическим транспортом по регулируемым тарифам;
100 тыс. рублей - для муниципального контракта на выполнение работ, связанных с осуществлением регулярных перевозок пассажиров и багажа автомобильным транспортом и городским наземным электрическим транспортом по регулируемым тарифам.', 'https://www.consultant.ru/document/cons_doc_LAW_155919/#dst100005', '9a7a90f7ea50d32b45af503ae57bfc60cba024bab5b9bfe5dc54708107849a22', NULL),
    ('pp1186/1(1)@2026-11-25:ef83e6125062', 'pp1186/1(1)', '2024-09-03', 'edition', NULL, NULL, '2026-11-25', '1(1). Установить предельный размер цены контракта, при которой или при превышении которой существенные условия заключенного на срок не менее 1 года контракта, предусмотренного частью 16 (при условии, что контракт жизненного цикла предусматривает проектирование, строительство, реконструкцию, капитальный ремонт объекта капитального строительства) и частью 16.1 статьи 34 Федерального закона "О контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд", контракта, предметом которого является выполнение работ по строительству, реконструкции, капитальному ремонту, сносу объекта капитального строительства, геологическому изучению недр, проведению работ по сохранению объектов культурного наследия, могут быть изменены в установленном порядке в случае возникновения при исполнении такого контракта независящих от сторон контракта обстоятельств, влекущих невозможность его исполнения, в том числе необходимость внесения изменений в проектную документацию, - 100 млн. рублей, за исключением контрактов, заключенных до 31 декабря 2022 г., в отношении которых такой предельный размер составляет 1 млн. рублей.', 'https://www.consultant.ru/document/cons_doc_LAW_155919/#dst4', 'ef83e6125062c18a6467e419a4773d9f4e22e5f1c6a67edac0774391d48fc339', NULL),
    ('pp1186/1(2)@2026-11-25:9d4f470c697a', 'pp1186/1(2)', '2024-09-03', 'edition', NULL, NULL, '2026-11-25', '1(2). Установить предельный размер цены контракта, при которой или при превышении которой существенные условия заключенного на срок не менее 1 года контракта, предметом которого является выполнение научно-исследовательских, опытно-конструкторских или технологических работ, могут быть изменены в установленном порядке в случае возникновения при исполнении такого контракта независящих от сторон контракта обстоятельств, влекущих невозможность его исполнения, - 100 млн. рублей.', 'https://www.consultant.ru/document/cons_doc_LAW_155919/#dst11', '9d4f470c697a67413ab428a2c4a12cce7d8e6f1a92d7669b436d0d16e81d6b10', NULL)
